/**
 * `sequence-catalog.json`: what the Nextcloud app needs to edit and validate
 * sequences without reaching this server. Every tool a step may call, with
 * its category, annotations and input schema (JSON Schema 2020-12, as the
 * SDK lists it), the built-in sequences, and the limits.
 *
 * Generated by `npm run catalog` into
 * `nextcloud-app/lib/Resources/sequence-catalog.json`; a test fails when the
 * committed file differs from what the code generates.
 */

import { z } from 'zod';
import { TOOL_REGISTRY } from '../tool-registry.js';
import { BUILTIN_SEQUENCES } from './builtin.js';
import { INPUT_TYPES, LIMITS, RESERVED_INPUTS, isSequenceTool } from './definition.js';

export const CATALOG_FORMAT = 'aiquila-sequence-catalog';
export const CATALOG_VERSION = 1;

const DESCRIPTION_CHARS = 300;

function shortDescription(text: string): string {
  const flat = text.replace(/\s+/g, ' ').trim();
  return flat.length > DESCRIPTION_CHARS ? `${flat.slice(0, DESCRIPTION_CHARS - 1)}…` : flat;
}

function jsonSchema(schema: z.ZodType): Record<string, unknown> {
  const out = z.toJSONSchema(schema, { io: 'input', unrepresentable: 'any' }) as Record<
    string,
    unknown
  >;
  delete out.$schema;
  return out;
}

export function buildCatalog() {
  return {
    format: CATALOG_FORMAT,
    version: CATALOG_VERSION,
    limits: {
      steps: LIMITS.steps,
      inputs: LIMITS.inputs,
      slugChars: LIMITS.slugChars,
      titleChars: LIMITS.titleChars,
      descriptionChars: LIMITS.descriptionChars,
    },
    inputTypes: [...INPUT_TYPES],
    reservedInputs: [...RESERVED_INPUTS],
    tools: TOOL_REGISTRY.flatMap((entry) =>
      entry.tools
        .filter((t) => !isSequenceTool(t.name))
        .map((t) => ({
          name: t.name,
          title: t.title,
          category: entry.category,
          description: shortDescription(t.description),
          annotations: t.annotations,
          inputSchema: jsonSchema(t.inputSchema as z.ZodType),
        }))
    ),
    builtins: BUILTIN_SEQUENCES.map(({ source: _source, ...def }) => def),
  };
}

/** The catalog as the committed file holds it. */
export function catalogJson(): string {
  return `${JSON.stringify(buildCatalog(), null, 1)}\n`;
}
